/// Whether a part is an enumerated item with a marker, or a bullet of an Acceptance section (no marker).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(super) enum PartKind {
    Enumerated,
    Bullet,
}

/// One explicit part of a request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(super) struct RequestPart {
    /// The marker without brackets (`3`, `c`); `None` for a bullet.
    pub marker: Option<String>,
    pub kind: PartKind,
    pub text: String,
    /// The alternatives group this part belongs to; any member covers it.
    pub group: Option<usize>,
    /// Whether the request says the part may be left out.
    pub optional: bool,
}

impl RequestPart {
    /// The part as the error names it: its marker and its text.
    pub(super) fn label(&self) -> String {
        match &self.marker {
            Some(m) => format!("({m}) {}", self.text),
            None => format!("bullet: {}", self.text),
        }
    }
}

/// A request read into its parts, the text around them and the corrections that follow it.
#[derive(Debug, Clone, Default)]
pub(super) struct ParsedRequest {
    pub parts: Vec<RequestPart>,
    /// The request's own text outside every part span.
    pub others: Vec<String>,
    /// The person's corrections, without their prefix.
    pub corrections: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MarkerStyle {
    ParenNum,
    ParenLetter,
    DotNum,
    CloseNum,
    CloseLetter,
}

#[derive(Debug, Clone)]
struct Marker {
    style: MarkerStyle,
    /// 1-based position in the sequence (`3`, or `c` as 3).
    ordinal: u32,
    value: String,
    start: usize,
    /// Where the part's text begins.
    end: usize,
}

/// The request with the retried job's request ahead of it and the corrections after it, so the parts check
/// reads the text a retry or a correction defers a part in. Each correction is one prefixed line.
pub(super) fn request_with_retried_parts(
    request: &str,
    corrections: &[String],
    attempt: Option<&EarlierAttempt>,
) -> String {
    let mut text = String::new();
    if let Some(a) = attempt {
        text.push_str(&a.request);
        text.push_str("\n\n");
    }
    text.push_str(request);
    let carried = attempt.map_or(&[][..], |a| a.corrections.as_slice());
    for correction in carried.iter().chain(corrections) {
        text.push('\n');
        text.push_str(USER_CORRECTION_PREFIX);
        text.push_str(&correction.replace(['\n', '\r'], " "));
    }
    text
}

fn is_section_heading(line: &str) -> bool {
    matches!(
        line.trim().to_lowercase().as_str(),
        "acceptance:" | "acceptance criteria:" | "## acceptance" | "## acceptance criteria"
    )
}

/// The marker and rest of a list line of an Acceptance section: `Some((None, text))` for a bullet,
/// `Some((Some(marker), text))` for an enumerated line, `None` for any other line.
fn section_list_line(line: &str) -> Option<(Option<String>, &str)> {
    let t = line.trim_start();
    if let Some(rest) = t.strip_prefix("- ").or_else(|| t.strip_prefix("* ")) {
        return Some((None, rest));
    }
    let digits = t.chars().take_while(char::is_ascii_digit).count();
    if digits > 0 && digits <= 2 {
        let (n, rest) = t.split_at(digits);
        if let Some(text) = rest.strip_prefix(". ") {
            return Some((None, text));
        }
        if let Some(text) = rest.strip_prefix(") ") {
            return Some((Some(n.trim_start_matches('0').to_string()), text));
        }
    }
    let bytes = t.as_bytes();
    if bytes.len() >= 4 && bytes[0] == b'(' && bytes[2] == b')' && bytes[3] == b' ' {
        let c = bytes[1] as char;
        if c.is_ascii_lowercase() {
            return Some((Some(c.to_string()), &t[4..]));
        }
    }
    if bytes.len() >= 3 && bytes[1] == b')' && bytes[2] == b' ' && bytes[0].is_ascii_lowercase() {
        return Some((Some((bytes[0] as char).to_string()), &t[3..]));
    }
    if digits > 0 && digits <= 2 && t[digits..].starts_with(')') {
        return None;
    }
    // `(N) text`
    if bytes.first() == Some(&b'(') {
        let inner = t[1..].chars().take_while(char::is_ascii_digit).count();
        if (1..=2).contains(&inner) && t[1 + inner..].starts_with(") ") {
            return Some((
                Some(t[1..1 + inner].trim_start_matches('0').to_string()),
                &t[inner + 3..],
            ));
        }
    }
    None
}

fn is_optional_text(text: &str) -> bool {
    let lower = text.trim_start().to_lowercase();
    lower.starts_with("optionally")
        || lower.contains("if time permits")
        || lower.contains("nice to have")
}

/// The text of a part cut at its trailing conjunction and punctuation; the flag says it ended in `or`.
fn trim_part_text(raw: &str) -> (String, bool) {
    let mut text = raw.trim().trim_end_matches(['.', ',', ';', ':']).trim().to_string();
    let mut ends_or = false;
    loop {
        let lower = text.to_lowercase();
        let cut = [" or", " and"].iter().find(|c| lower.ends_with(**c)).copied();
        match cut {
            Some(c) => {
                ends_or |= c == " or";
                text.truncate(text.len() - c.len());
                text = text.trim().trim_end_matches([',', ';']).trim().to_string();
            }
            None => break,
        }
    }
    (text, ends_or)
}

fn ordinal_of(style: MarkerStyle, value: &str) -> u32 {
    match style {
        MarkerStyle::ParenNum | MarkerStyle::DotNum | MarkerStyle::CloseNum => {
            value.parse().unwrap_or(0)
        }
        _ => value
            .bytes()
            .next()
            .map_or(0, |b| u32::from(b.saturating_sub(b'a')) + 1),
    }
}

fn scan_markers(body: &str) -> Vec<Marker> {
    let bytes = body.as_bytes();
    let mut markers: Vec<Marker> = Vec::new();
    let boundary_before = |i: usize| i == 0 || !bytes[i - 1].is_ascii_alphanumeric();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'(' && boundary_before(i) {
            let digits = bytes[i + 1..].iter().take_while(|b| b.is_ascii_digit()).count();
            if (1..=2).contains(&digits) && bytes.get(i + 1 + digits) == Some(&b')') {
                let value = body[i + 1..i + 1 + digits].trim_start_matches('0').to_string();
                markers.push(Marker {
                    style: MarkerStyle::ParenNum,
                    ordinal: ordinal_of(MarkerStyle::ParenNum, &value),
                    value,
                    start: i,
                    end: i + digits + 2,
                });
            } else if bytes.get(i + 1).is_some_and(u8::is_ascii_lowercase)
                && bytes.get(i + 2) == Some(&b')')
            {
                let value = (bytes[i + 1] as char).to_string();
                markers.push(Marker {
                    style: MarkerStyle::ParenLetter,
                    ordinal: ordinal_of(MarkerStyle::ParenLetter, &value),
                    value,
                    start: i,
                    end: i + 3,
                });
            }
        }
        i += 1;
    }
    let mut offset = 0;
    for line in body.split_inclusive('\n') {
        let lead = line.len() - line.trim_start().len();
        let t = &line[lead..];
        let at = offset + lead;
        let digits = t.chars().take_while(char::is_ascii_digit).count();
        if (1..=2).contains(&digits) {
            let value = t[..digits].trim_start_matches('0').to_string();
            if t[digits..].starts_with(". ") {
                markers.push(Marker {
                    style: MarkerStyle::DotNum,
                    ordinal: ordinal_of(MarkerStyle::DotNum, &value),
                    value,
                    start: at,
                    end: at + digits + 2,
                });
            } else if t[digits..].starts_with(") ") {
                markers.push(Marker {
                    style: MarkerStyle::CloseNum,
                    ordinal: ordinal_of(MarkerStyle::CloseNum, &value),
                    value,
                    start: at,
                    end: at + digits + 2,
                });
            }
        } else if t.len() >= 3
            && t.as_bytes()[0].is_ascii_lowercase()
            && t[1..].starts_with(") ")
        {
            let value = t[..1].to_string();
            markers.push(Marker {
                style: MarkerStyle::CloseLetter,
                ordinal: ordinal_of(MarkerStyle::CloseLetter, &value),
                value,
                start: at,
                end: at + 3,
            });
        }
        offset += line.len();
    }
    markers.sort_by_key(|m| m.start);
    markers
}

/// The runs of consecutive markers (starting at 1 or `a`) of each style, ordered by where they start.
fn marker_runs(markers: &[Marker]) -> Vec<Vec<Marker>> {
    let styles = [
        MarkerStyle::ParenNum,
        MarkerStyle::ParenLetter,
        MarkerStyle::DotNum,
        MarkerStyle::CloseNum,
        MarkerStyle::CloseLetter,
    ];
    let mut runs: Vec<Vec<Marker>> = Vec::new();
    for style in styles {
        let mut current: Vec<Marker> = Vec::new();
        for m in markers.iter().filter(|m| m.style == style) {
            if m.ordinal == 1 {
                if current.len() >= 2 {
                    runs.push(std::mem::take(&mut current));
                }
                current = vec![m.clone()];
            } else if current.last().is_some_and(|l| l.ordinal + 1 == m.ordinal) {
                current.push(m.clone());
            }
        }
        if current.len() >= 2 {
            runs.push(current);
        }
    }
    runs.sort_by_key(|r| r[0].start);
    runs
}

/// The enumerated parts of the text before an Acceptance section, and the text around them.
fn enumerated_parts(body: &str, next_group: &mut usize) -> (Vec<RequestPart>, String) {
    let runs = marker_runs(&scan_markers(body));
    let mut parts: Vec<RequestPart> = Vec::new();
    let mut spans: Vec<(usize, usize)> = Vec::new();
    for run in runs {
        if spans.iter().any(|(s, e)| run[0].start >= *s && run[0].start < *e) {
            continue;
        }
        let mut members: Vec<(RequestPart, bool)> = Vec::new();
        let mut run_spans: Vec<(usize, usize)> = Vec::new();
        for (k, m) in run.iter().enumerate() {
            let mut end = body[m.end..].find('\n').map_or(body.len(), |p| m.end + p);
            if let Some(p) = body[m.end..end].find(". ") {
                end = m.end + p + 1;
            }
            if let Some(next) = run.get(k + 1) {
                end = end.min(next.start);
            }
            let (text, ends_or) = trim_part_text(&body[m.end..end]);
            run_spans.push((m.start, end));
            if part_stems(&text).is_empty() {
                continue;
            }
            members.push((
                RequestPart {
                    marker: Some(m.value.clone()),
                    kind: PartKind::Enumerated,
                    optional: is_optional_text(&text),
                    text,
                    group: None,
                },
                ends_or,
            ));
        }
        if members.len() < 2 {
            continue;
        }
        spans.extend(run_spans);
        let first = run[0].start;
        let last = run[run.len() - 1].start;
        let boundary = [body[..first].rfind(". ").map(|p| p + 1), body[..first].rfind("\n\n")]
            .into_iter()
            .flatten()
            .max()
            .unwrap_or(0);
        let preceding = body[boundary..first].to_lowercase();
        let inline = matches!(run[0].style, MarkerStyle::ParenNum | MarkerStyle::ParenLetter);
        let all = ALT_INTRODUCERS.iter().any(|p| preceding.contains(p))
            || (preceding.contains("either") && body[boundary..last].to_lowercase().contains(" or "))
            || (inline && members.len() >= 2 && members[members.len() - 2].1);
        if all {
            *next_group += 1;
            for (p, _) in &mut members {
                p.group = Some(*next_group);
            }
        } else {
            let mut k = 0;
            while k + 1 < members.len() {
                if members[k].1 {
                    let id = members[k].0.group.unwrap_or_else(|| {
                        *next_group += 1;
                        *next_group
                    });
                    members[k].0.group = Some(id);
                    members[k + 1].0.group = Some(id);
                }
                k += 1;
            }
        }
        parts.extend(members.into_iter().map(|(p, _)| p));
    }
    spans.sort();
    let mut others = String::new();
    let mut at = 0;
    for (s, e) in spans {
        if s >= at {
            others.push_str(&body[at..s]);
            others.push('\n');
            at = e.max(at);
        }
    }
    others.push_str(&body[at.min(body.len())..]);
    (parts, others)
}

/// Reads a request into its explicit parts: enumerated items before an Acceptance section, and the list lines
/// of the section (see [`is_section_heading`]; the section ends at the first unindented line that is not a
/// list line). Lines Athena's generators wrote or copied and fenced code are left out
/// ([`super::terms::request_own_lines`]); lines that start with [`USER_CORRECTION_PREFIX`] are corrections.
pub(super) fn parse_request(request: &str) -> ParsedRequest {
    let mut lines = super::terms::request_own_lines(request);
    if request.contains(super::terms::APPROVAL_ANCHOR) && !lines.is_empty() {
        lines.remove(0);
    }
    let mut parsed = ParsedRequest::default();
    let mut before: Vec<&str> = Vec::new();
    let mut state = 0u8; // 0 before the heading, 1 in the section, 2 after it
    let mut section_others: Vec<String> = Vec::new();
    let mut next_group = 0usize;
    for line in lines {
        if let Some(text) = line.strip_prefix(USER_CORRECTION_PREFIX) {
            parsed.corrections.push(text.trim().to_string());
            continue;
        }
        match state {
            0 if is_section_heading(line) => state = 1,
            0 => before.push(line),
            1 => match section_list_line(line) {
                Some((marker, text)) => {
                    let (text, _) = trim_part_text(text);
                    if part_stems(&text).is_empty() {
                        continue;
                    }
                    parsed.parts.push(RequestPart {
                        kind: if marker.is_some() {
                            PartKind::Enumerated
                        } else {
                            PartKind::Bullet
                        },
                        marker,
                        optional: is_optional_text(&text),
                        text,
                        group: None,
                    });
                }
                None if line.trim().is_empty() || line.starts_with(char::is_whitespace) => {
                    section_others.push(line.to_string());
                }
                None => {
                    state = 2;
                    section_others.push(line.to_string());
                }
            },
            _ => section_others.push(line.to_string()),
        }
    }
    let (mut enumerated, others) = enumerated_parts(&before.join("\n"), &mut next_group);
    enumerated.append(&mut parsed.parts);
    parsed.parts = enumerated;
    parsed.others.push(others);
    parsed.others.extend(section_others);
    parsed
}

/// The explicit parts of a request (see [`parse_request`]).
#[cfg(test)]
pub(super) fn request_parts(request: &str) -> Vec<RequestPart> {
    parse_request(request).parts
}

fn contains_bounded(hay: &str, needle: &str) -> bool {
    let first_alnum = needle.chars().next().is_some_and(char::is_alphanumeric);
    let last_alnum = needle.chars().last().is_some_and(char::is_alphanumeric);
    hay.match_indices(needle).any(|(at, _)| {
        let before_ok = !first_alnum
            || hay[..at].chars().next_back().is_none_or(|c| !c.is_alphanumeric());
        let after_ok = !last_alnum
            || hay[at + needle.len()..].chars().next().is_none_or(|c| !c.is_alphanumeric());
        before_ok && after_ok
    })
}

fn find_phrase<'a>(hay: &str, phrases: &[&'a str]) -> Option<&'a str> {
    phrases.iter().copied().find(|p| contains_bounded(hay, p))
}

fn split_clauses(lower: &str, separators: &[&str]) -> Vec<String> {
    let mut text = lower.to_string();
    for sep in separators {
        text = text.replace(sep, "\u{1}");
    }
    text.split('\u{1}').map(|c| c.trim().to_string()).filter(|c| !c.is_empty()).collect()
}

fn split_sentences(text: &str) -> Vec<String> {
    text.replace(['\n', '\r'], ". ")
        .replace("! ", ". ")
        .replace("? ", ". ")
        .split(". ")
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

/// Whether lowercase `text` cites the part marker `marker`: `(3)`, `part 3`, `item 3`, or, when `bare` is set,
/// the number alone before a bracket (`3)`).
pub(super) fn cites_marker(lower: &str, marker: &str, bare: bool) -> bool {
    contains_bounded(lower, &format!("({marker})"))
        || contains_bounded(lower, &format!("part {marker}"))
        || contains_bounded(lower, &format!("item {marker}"))
        || (bare
            && marker.chars().all(|c| c.is_ascii_digit())
            && contains_bounded(lower, &format!("{marker})")))
}

fn stem_of(word: &str, path: bool) -> Option<String> {
    let w = word.to_ascii_lowercase();
    if w.len() < 3 || w.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let s = if w.len() > 3 { w.strip_suffix('s').unwrap_or(&w) } else { &w };
    let listed = |list: &[&str]| list.contains(&w.as_str()) || list.contains(&s);
    if listed(FUNCTION_WORDS)
        || listed(&COMMON_WORDS)
        || listed(PART_FILLER)
        || listed(TEXT_PATH_WORDS)
        || (path && listed(PATH_ONLY_WORDS))
    {
        return None;
    }
    let cut: String = s.chars().take(6).collect();
    Some(if cut == "doc" { "docume".to_string() } else { cut })
}

fn stems_of_words(text: &str, path: bool) -> BTreeSet<String> {
    text.split(|c: char| !c.is_ascii_alphanumeric())
        .filter(|w| !w.is_empty())
        .filter_map(|w| stem_of(w, path))
        .collect()
}

/// The distinctive stems of a part's text: lowercase words of 3+ letters, stripped of a plural `s`, without
/// function, common, check-method and path words, cut to 6 letters.
pub(super) fn part_stems(text: &str) -> BTreeSet<String> {
    let text = text.trim_start();
    let text = match text.strip_prefix('[').and_then(|r| r.split_once(']')) {
        Some((_, rest)) => rest,
        None => text,
    };
    stems_of_words(text, false)
}

/// A criterion's text without the parts that name how it is checked: backtick spans and unquoted spans that
/// start with `cargo` or `git`, and tokens that are paths or identifiers.
fn clean_criterion(text: &str) -> String {
    let mut plain = String::new();
    let mut rest = text;
    while let Some(open) = rest.find('`') {
        plain.push_str(&rest[..open]);
        match rest[open + 1..].find('`') {
            Some(len) => {
                let inner = &rest[open + 1..open + 1 + len];
                let first = inner.split_whitespace().next().unwrap_or("");
                if first != "cargo" && first != "git" {
                    plain.push(' ');
                    plain.push_str(inner);
                    plain.push(' ');
                }
                rest = &rest[open + len + 2..];
            }
            None => {
                plain.push_str(&rest[open + 1..]);
                rest = "";
            }
        }
    }
    plain.push_str(rest);
    let mut kept: Vec<&str> = Vec::new();
    let mut skipping = false;
    for token in plain.split_whitespace() {
        let bare = token.trim_matches(|c: char| !c.is_ascii_alphanumeric());
        if !skipping && (bare == "cargo" || bare == "git") {
            skipping = true;
        }
        if skipping {
            if token.ends_with(['.', ';', ',', ')']) {
                skipping = false;
            }
            continue;
        }
        if token.contains('/') || token.contains('_') || token.contains("::") {
            continue;
        }
        kept.push(token);
    }
    kept.join(" ")
}

/// The stems of a criterion's text, cleaned of commands and paths (see [`clean_criterion`]).
pub(super) fn criterion_stems(text: &str) -> BTreeSet<String> {
    part_stems(&clean_criterion(text))
}

/// The stems of a deliverable path: its words other than path and file-type words, `test`, `tests` and `json`.
pub(super) fn path_stems(path: &str) -> BTreeSet<String> {
    stems_of_words(path, true)
}

/// Whether two stems name the same word: equal, or the shorter has 4+ letters and is a prefix of the other.
pub(super) fn stems_match(a: &str, b: &str) -> bool {
    let (short, long) = if a.len() <= b.len() { (a, b) } else { (b, a) };
    short == long || (short.len() >= 4 && long.starts_with(short))
}

/// How many of `wanted` some stem of `have` matches.
pub(super) fn matched_stems(wanted: &BTreeSet<String>, have: &BTreeSet<String>) -> usize {
    wanted.iter().filter(|w| have.iter().any(|h| stems_match(w, h))).count()
}

/// Each part's stems after the stems that occur in every part of its kind are dropped (all of them when that
/// would leave none).
pub(super) fn distinctive_stems(parts: &[RequestPart]) -> Vec<BTreeSet<String>> {
    let full: Vec<BTreeSet<String>> = parts.iter().map(|p| part_stems(&p.text)).collect();
    parts
        .iter()
        .enumerate()
        .map(|(i, p)| {
            let peers: Vec<&BTreeSet<String>> = parts
                .iter()
                .enumerate()
                .filter(|(j, q)| *j != i && q.kind == p.kind)
                .map(|(j, _)| &full[j])
                .collect();
            if peers.is_empty() {
                return full[i].clone();
            }
            let kept: BTreeSet<String> = full[i]
                .iter()
                .filter(|s| !peers.iter().all(|q| q.iter().any(|t| stems_match(s, t))))
                .cloned()
                .collect();
            if kept.is_empty() { full[i].clone() } else { kept }
        })
        .collect()
}

/// The phrase that makes `criterion` unusable for `part`, if a clause that names the part's subject (or, for a
/// marked part, cites its marker) holds one. A phrase the part's own text holds does not count.
pub(super) fn negation_hit(
    criterion: &str,
    part: &RequestPart,
    distinct: &BTreeSet<String>,
) -> Option<&'static str> {
    let lower = criterion.to_lowercase();
    let marker = part.marker.as_deref().filter(|_| part.kind == PartKind::Enumerated);
    let list = if marker.is_some() { CRITERION_MARKER_NEGATION } else { CRITERION_NEGATION };
    let own = part.text.to_lowercase();
    for clause in split_clauses(&lower, CRITERION_CLAUSE_SEPARATORS) {
        let relevant = matched_stems(distinct, &part_stems(&clause)) > 0
            || marker.is_some_and(|m| cites_marker(&clause, m, false));
        if !relevant {
            continue;
        }
        if let Some(phrase) = list
            .iter()
            .copied()
            .find(|p| contains_bounded(&clause, p) && !contains_bounded(&own, p))
        {
            return Some(phrase);
        }
    }
    None
}

fn has_negator(clause: &str) -> bool {
    let mut c = clause.to_string();
    for p in ["not in this job", "not part of", "not done", "not covered"] {
        c = c.replace(p, " ");
    }
    c.split(|ch: char| !(ch.is_alphanumeric() || ch == '\'' || ch == '\u{2019}'))
        .any(|w| matches!(w, "not" | "never" | "cannot") || w.ends_with("n't"))
}

/// Whether one clause of a request or a correction defers work: a [`REQUEST_DEFERRAL`] phrase, or `later` as
/// the last word, or in `at a later`, `for later`, `for a later`, `come later`; and no negator in the clause.
fn clause_defers(clause: &str) -> bool {
    let c = clause.trim().trim_end_matches(['.', ',', ';', ':', '!', '?', ')', '"', '\'']).trim();
    let later = c.rsplit(|ch: char| !ch.is_alphanumeric()).next() == Some("later")
        || ["at a later", "for later", "for a later", "come later"]
            .iter()
            .any(|p| contains_bounded(c, p));
    (find_phrase(c, REQUEST_DEFERRAL).is_some() || later) && !has_negator(c)
}

/// Why a request, a retried request or a correction defers `part`, if it does: its own text holds a
/// [`DEFER_PHRASES`] phrase; or another sentence of the request cites its marker and defers in some clause; or a
/// correction defers in a clause that cites its marker or shares `need` distinctive stems with it.
pub(super) fn part_deferred(
    part: &RequestPart,
    distinct: &BTreeSet<String>,
    need: usize,
    parsed: &ParsedRequest,
) -> Option<String> {
    let own = part.text.to_lowercase();
    if let Some(p) = find_phrase(&own, DEFER_PHRASES) {
        return Some(format!("its own text says \"{p}\""));
    }
    let marker = part.marker.as_deref().filter(|_| part.kind == PartKind::Enumerated);
    if let Some(m) = marker {
        for other in &parsed.others {
            for sentence in split_sentences(&other.to_lowercase()) {
                if cites_marker(&sentence, m, true)
                    && split_clauses(&sentence, REQUEST_CLAUSE_SEPARATORS)
                        .iter()
                        .any(|c| clause_defers(c))
                {
                    return Some(format!("the request says \"{sentence}\""));
                }
            }
        }
    }
    for correction in &parsed.corrections {
        for sentence in split_sentences(&correction.to_lowercase()) {
            for clause in split_clauses(&sentence, REQUEST_CLAUSE_SEPARATORS) {
                let names = marker.is_some_and(|m| cites_marker(&clause, m, true))
                    || (need > 0 && matched_stems(distinct, &part_stems(&clause)) >= need);
                if names && clause_defers(&clause) {
                    return Some(format!("a correction says \"{sentence}\""));
                }
            }
        }
    }
    None
}
